{"command":"cat << 'EOF' > src/args.rs
use std::env;
use std::path::PathBuf;

#[derive(Debug, Default)]
pub struct Args {
    pub default: Option<String>,
    pub out_file: Option<PathBuf>,
    pub in_file: Option<PathBuf>,
    pub config_reference: bool,
    pub raw_mode: bool,
    pub no_isolation: bool,
    pub help: bool,
}

pub fn parse_args() -> Result<Args, i32> {
    let mut args_iter = env::args().skip(1);
    let mut parsed = Args::default();
    let prog_name = env::args().next().unwrap_or_else(|| "./executable".to_string());

    while let Some(arg) = args_iter.next() {
        match arg.as_str() {
            "-h" | "--help" => {
                parsed.help = true;
            }
            "--config-reference" => {
                parsed.config_reference = true;
            }
            "-r" | "--raw-mode" => {
                parsed.raw_mode = true;
            }
            "--no-isolation" => {
                parsed.no_isolation = true;
            }
            "-d" | "--default" => {
                if let Some(val) = args_iter.next() {
                    parsed.default = Some(val);
                } else {
                    let opt_name = if arg == "-d" { "d" } else { "default" };
                    eprintln!("{}: Argument to option '{}' missing", prog_name, opt_name);
                    return Err(1);
                }
            }
            "-o" | "--out-file" => {
                if let Some(val) = args_iter.next() {
                    parsed.out_file = Some(PathBuf::from(val));
                } else {
                    let opt_name = if arg == "-o" { "o" } else { "out-file" };
                    eprintln!("{}: Argument to option '{}' missing", prog_name, opt_name);
                    return Err(1);
                }
            }
            "--in-file" => {
                if let Some(val) = args_iter.next() {
                    parsed.in_file = Some(PathBuf::from(val));
                } else {
                    eprintln!("{}: Argument to option 'in-file' missing", prog_name);
                    return Err(1);
                }
            }
            s if s.starts_with('-') => {
                let opt = s.trim_start_matches('-');
                eprintln!("{}: Unrecognized option: '{}'", prog_name, opt);
                return Err(1);
            }
            _ => {
                // Free positional arguments are ignored
            }
        }
    }

    Ok(parsed)
}

pub fn print_help() {
    let prog_name = env::args().next().unwrap_or_else(|| "./executable".to_string());
    println!("Usage: {} [options]\n", prog_name);
    println!("Options:");
    println!("    -d, --default TEXT  text inserted into the textfield on startup");
    println!("    -o, --out-file FILE write final command to file");
    println!("        --in-file FILE  read initial command from file");
    println!("        --config-reference ");
    println!("                        print out the default configuration file");
    println!("    -r, --raw-mode      keep linebreaks in finished command when closing");
    println!("        --no-isolation  disable isolation. This will run the commands directly");
    println!("                        on your system, without protection. Take care.");
    println!("    -h, --help          print this help menu");
}
EOF"}

