{"command":"cat << 'EOF' > src/config.rs
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::fs;
use std::path::PathBuf;

pub const DEFAULT_CONFIG_STR: &str = r#"
#  ____  _
# |  _ \(_)_ __  _ __       .________.
# | |_) | | '_ \| '__|      |________|
# |  __/| | |_) | |          |_    -|
# |_|   |_| .__/|_|     xX  xXx___x_|
#         |_|
#
# A commandline utility by
# Leon Kowarschick

# finish_hook: Executed once you close pipr, getting the command you constructed piped into stdin.
# finish_hook = "xclip -selection clipboard -in"

# Paranoid history mode writes every sucessfully running command into the history in autoeval mode.
paranoid_history_mode_default = false

autoeval_mode_default = true

history_size = 500
cmdlist_always_show_preview = false
cmd_timeout_millis = 2000

highlighting_enabled = true

eval_environment = ["bash", "-c"]

# Snippets can be used to quickly insert common bits of shell
# use || (two pipes) where you want your cursor to be after insertion
[snippets]
s = " | sed -r 's/||//g'"

[help_viewers]
'm' = "man ??"
'h' = "?? --help | less"

[output_viewers]
'l' = "less"
"#;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Config {
    #[serde(default = "default_false")]
    pub paranoid_history_mode_default: bool,

    #[serde(default = "default_true")]
    pub autoeval_mode_default: bool,

    #[serde(default = "default_history_size")]
    pub history_size: usize,

    #[serde(default = "default_false")]
    pub cmdlist_always_show_preview: bool,

    #[serde(default = "default_timeout")]
    pub cmd_timeout_millis: u64,

    #[serde(default = "default_true")]
    pub highlighting_enabled: bool,

    #[serde(default = "default_eval_env")]
    pub eval_environment: Vec<String>,

    pub finish_hook: Option<String>,

    #[serde(default)]
    pub snippets: BTreeMap<char, String>,

    #[serde(default)]
    pub help_viewers: BTreeMap<char, String>,

    #[serde(default)]
    pub output_viewers: BTreeMap<char, String>,
}

fn default_false() -> bool { false }
fn default_true() -> bool { true }
fn default_history_size() -> usize { 500 }
fn default_timeout() -> u64 { 2000 }
fn default_eval_env() -> Vec<String> { vec!["bash".to_string(), "-c".to_string()] }

impl Default for Config {
    fn default() -> Self {
        toml::from_str(DEFAULT_CONFIG_STR).unwrap_or_else(|_| Config {
            paranoid_history_mode_default: false,
            autoeval_mode_default: true,
            history_size: 500,
            cmdlist_always_show_preview: false,
            cmd_timeout_millis: 2000,
            highlighting_enabled: true,
            eval_environment: vec!["bash".to_string(), "-c".to_string()],
            finish_hook: None,
            snippets: BTreeMap::new(),
            help_viewers: BTreeMap::new(),
            output_viewers: BTreeMap::new(),
        })
    }
}

pub fn get_config_dir() -> PathBuf {
    if let Ok(home) = std::env::var("HOME") {
        PathBuf::from(home).join(".config").join("pipr")
    } else {
        PathBuf::from(".config/pipr")
    }
}

pub fn load_or_create_config() -> Config {
    let dir = get_config_dir();
    let config_path = dir.join("pipr.toml");

    if !config_path.exists() {
        let _ = fs::create_dir_all(&dir);
        let _ = fs::write(&config_path, DEFAULT_CONFIG_STR);
        Config::default()
    } else {
        match fs::read_to_string(&config_path) {
            Ok(content) => toml::from_str(&content).unwrap_or_else(|_| Config::default()),
            Err(_) => Config::default(),
        }
    }
}
EOF"}

