use std::io::Write;
use std::process::{Command, Stdio};
use std::time::Duration;
use std::thread;

pub struct ExecResult {
    pub stdout: String,
    pub stderr: String,
}

pub fn execute_command(
    command_str: &str,
    eval_env: &[String],
    no_isolation: bool,
    timeout_millis: u64,
    cached_stdin: Option<&str>,
) -> ExecResult {
    let clean_cmd = prepare_command_string(command_str);
    if clean_cmd.trim().is_empty() {
        return ExecResult {
            stdout: String::new(),
            stderr: String::new(),
        };
    }

    if eval_env.is_empty() {
        return ExecResult {
            stdout: String::new(),
            stderr: "Error: eval_environment is empty".to_string(),
        };
    }

    let mut cmd = if no_isolation {
        let mut c = Command::new(&eval_env[0]);
        c.args(&eval_env[1..]);
        c.arg(&clean_cmd);
        c
    } else {
        let mut c = Command::new("bwrap");
        c.args(&[
            "--ro-bind", "/", "/",
            "--tmpfs", "/tmp",
            "--dev", "/dev",
            "--proc", "/proc",
            "--die-with-parent", "--share-net",
            "--unshare-pid",
        ]);
        c.args(eval_env);
        c.arg(&clean_cmd);
        c
    };

    cmd.stdout(Stdio::piped());
    cmd.stderr(Stdio::piped());
    if cached_stdin.is_some() {
        cmd.stdin(Stdio::piped());
    } else {
        cmd.stdin(Stdio::null());
    }

    let mut child = match cmd.spawn() {
        Ok(c) => c,
        Err(e) => {
            return ExecResult {
                stdout: String::new(),
                stderr: format!("Failed to spawn command: {}", e),
            };
        }
    };

    if let Some(stdin_data) = cached_stdin {
        if let Some(mut stdin) = child.stdin.take() {
            let data = stdin_data.as_bytes().to_vec();
            thread::spawn(move || {
                let _ = stdin.write_all(&data);
            });
        }
    }

    let stdout_handle = child.stdout.take();
    let stderr_handle = child.stderr.take();

    let (stdout_tx, stdout_rx) = std::sync::mpsc::channel();
    let (stderr_tx, stderr_rx) = std::sync::mpsc::channel();

    if let Some(mut out) = stdout_handle {
        thread::spawn(move || {
            use std::io::Read;
            let mut buf = Vec::new();
            let _ = out.read_to_end(&mut buf);
            let _ = stdout_tx.send(String::from_utf8_lossy(&buf).to_string());
        });
    } else {
        let _ = stdout_tx.send(String::new());
    }

    if let Some(mut err) = stderr_handle {
        thread::spawn(move || {
            use std::io::Read;
            let mut buf = Vec::new();
            let _ = err.read_to_end(&mut buf);
            let _ = stderr_tx.send(String::from_utf8_lossy(&buf).to_string());
        });
    } else {
        let _ = stderr_tx.send(String::new());
    }

    let start = std::time::Instant::now();
    let timeout = Duration::from_millis(timeout_millis);

    loop {
        match child.try_wait() {
            Ok(Some(_status)) => {
                let stdout = stdout_rx.recv().unwrap_or_default();
                let stderr = stderr_rx.recv().unwrap_or_default();
                return ExecResult { stdout, stderr };
            }
            Ok(None) => {
                if start.elapsed() >= timeout {
                    let _ = child.kill();
                    let _ = child.wait();
                    return ExecResult {
                        stdout: String::new(),
                        stderr: String::new(),
                    };
                }
                thread::sleep(Duration::from_millis(10));
            }
            Err(_) => {
                let _ = child.kill();
                return ExecResult {
                    stdout: String::new(),
                    stderr: "Execution error".to_string(),
                };
            }
        }
    }
}

pub fn prepare_command_string(full_input: &str) -> String {
    let mut valid_lines = Vec::new();
    for line in full_input.lines() {
        let trimmed = line.trim_start();
        if !trimmed.starts_with('#') {
            valid_lines.push(line.trim());
        }
    }
    valid_lines.join(" ")
}
EOF"}

