{"command":"cat << 'EOF' > src/editor.rs
#[derive(Debug, Clone, Default)]
pub struct Editor {
    pub lines: Vec<String>,
    pub cursor_y: usize,
    pub cursor_x: usize,
}

impl Editor {
    pub fn new() -> Self {
        Self {
            lines: vec![String::new()],
            cursor_y: 0,
            cursor_x: 0,
        }
    }

    pub fn from_str(text: &str) -> Self {
        let mut ed = Self::new();
        ed.set_text(text);
        ed
    }

    pub fn set_text(&mut self, text: &str) {
        let lines: Vec<String> = text.lines().map(|s| s.to_string()).collect();
        if lines.is_empty() {
            self.lines = vec![String::new()];
        } else {
            self.lines = lines;
        }
        self.cursor_y = self.lines.len() - 1;
        self.cursor_x = self.lines[self.cursor_y].chars().count();
    }

    pub fn get_full_text(&self) -> String {
        self.lines.join("\n")
    }

    pub fn clear(&mut self) {
        self.lines = vec![String::new()];
        self.cursor_y = 0;
        self.cursor_x = 0;
    }

    pub fn insert_char(&mut self, c: char) {
        if self.cursor_y >= self.lines.len() {
            self.lines.resize(self.cursor_y + 1, String::new());
        }
        let line = &mut self.lines[self.cursor_y];
        let char_count = line.chars().count();
        if self.cursor_x > char_count {
            self.cursor_x = char_count;
        }

        let byte_idx = line
            .char_indices()
            .nth(self.cursor_x)
            .map(|(i, _)| i)
            .unwrap_or(line.len());
        line.insert(byte_idx, c);
        self.cursor_x += 1;
    }

    pub fn insert_newline(&mut self) {
        let line = &mut self.lines[self.cursor_y];
        let byte_idx = line
            .char_indices()
            .nth(self.cursor_x)
            .map(|(i, _)| i)
            .unwrap_or(line.len());

        let remainder = line[byte_idx..].to_string();
        line.truncate(byte_idx);

        self.lines.insert(self.cursor_y + 1, remainder);
        self.cursor_y += 1;
        self.cursor_x = 0;
    }

    pub fn backspace(&mut self) {
        if self.cursor_x > 0 {
            let line = &mut self.lines[self.cursor_y];
            let byte_idx = line
                .char_indices()
                .nth(self.cursor_x - 1)
                .map(|(i, _)| i)
                .unwrap_or(0);
            line.remove(byte_idx);
            self.cursor_x -= 1;
        } else if self.cursor_y > 0 {
            let current_line = self.lines.remove(self.cursor_y);
            self.cursor_y -= 1;
            let prev_line = &mut self.lines[self.cursor_y];
            self.cursor_x = prev_line.chars().count();
            prev_line.push_str(&current_line);
        }
    }

    pub fn delete(&mut self) {
        let line_len = self.lines[self.cursor_y].chars().count();
        if self.cursor_x < line_len {
            let line = &mut self.lines[self.cursor_y];
            let byte_idx = line
                .char_indices()
                .nth(self.cursor_x)
                .map(|(i, _)| i)
                .unwrap_or(0);
            line.remove(byte_idx);
        } else if self.cursor_y + 1 < self.lines.len() {
            let next_line = self.lines.remove(self.cursor_y + 1);
            self.lines[self.cursor_y].push_str(&next_line);
        }
    }

    pub fn move_left(&mut self) {
        if self.cursor_x > 0 {
            self.cursor_x -= 1;
        } else if self.cursor_y > 0 {
            self.cursor_y -= 1;
            self.cursor_x = self.lines[self.cursor_y].chars().count();
        }
    }

    pub fn move_right(&mut self) {
        let line_len = self.lines[self.cursor_y].chars().count();
        if self.cursor_x < line_len {
            self.cursor_x += 1;
        } else if self.cursor_y + 1 < self.lines.len() {
            self.cursor_y += 1;
            self.cursor_x = 0;
        }
    }

    pub fn move_up(&mut self) {
        if self.cursor_y > 0 {
            self.cursor_y -= 1;
            let line_len = self.lines[self.cursor_y].chars().count();
            if self.cursor_x > line_len {
                self.cursor_x = line_len;
            }
        }
    }

    pub fn move_down(&mut self) {
        if self.cursor_y + 1 < self.lines.len() {
            self.cursor_y += 1;
            let line_len = self.lines[self.cursor_y].chars().count();
            if self.cursor_x > line_len {
                self.cursor_x = line_len;
            }
        }
    }

    pub fn move_home(&mut self) {
        self.cursor_x = 0;
    }

    pub fn move_end(&mut self) {
        self.cursor_x = self.lines[self.cursor_y].chars().count();
    }

    pub fn is_cursor_on_pipe(&self) -> bool {
        if self.cursor_y >= self.lines.len() {
            return false;
        }
        let line = &self.lines[self.cursor_y];
        line.chars().nth(self.cursor_x) == Some('|')
    }

    pub fn get_word_under_cursor(&self) -> String {
        if self.cursor_y >= self.lines.len() {
            return String::new();
        }
        let line = &self.lines[self.cursor_y];
        let chars: Vec<char> = line.chars().collect();
        if chars.is_empty() {
            return String::new();
        }

        let idx = self.cursor_x.min(chars.len().saturating_sub(1));
        let is_word_char = |c: char| c.is_alphanumeric() || c == '_' || c == '-';

        if !is_word_char(chars[idx]) {
            return String::new();
        }

        let mut start = idx;
        while start > 0 && is_word_char(chars[start - 1]) {
            start -= 1;
        }

        let mut end = idx;
        while end + 1 < chars.len() && is_word_char(chars[end + 1]) {
            end += 1;
        }

        chars[start..=end].iter().collect()
    }

    pub fn get_text_up_to_cursor(&self) -> String {
        let mut parts = Vec::new();
        for (y, line) in self.lines.iter().enumerate() {
            if y < self.cursor_y {
                parts.push(line.clone());
            } else if y == self.cursor_y {
                let text: String = line.chars().take(self.cursor_x + 1).collect();
                parts.push(text);
                break;
            }
        }
        parts.join(" ")
    }

    pub fn get_text_after_cursor(&self) -> String {
        let mut parts = Vec::new();
        for (y, line) in self.lines.iter().enumerate() {
            if y == self.cursor_y {
                let text: String = line.chars().skip(self.cursor_x + 1).collect();
                parts.push(text);
            } else if y > self.cursor_y {
                parts.push(line.clone());
            }
        }
        parts.join(" ")
    }

    pub fn insert_str_at_cursor(&mut self, text: &str) -> Option<usize> {
        // If text contains ||, record target cursor offset
        let target_cursor_offset = text.find("||");
        let clean_text = text.replace("||", "");

        for c in clean_text.chars() {
            if c == '\n' {
                self.insert_newline();
            } else {
                self.insert_char(c);
            }
        }

        if let Some(offset) = target_cursor_offset {
            // Reposition cursor to offset
            let back = clean_text.chars().count() - offset;
            for _ in 0..back {
                self.move_left();
            }
        }

        target_cursor_offset
    }
}
EOF"}

