use ratatui::style::{Color, Style};
use ratatui::text::{Line, Span};

const COLOR_CMD: Color = Color::Rgb(150, 181, 180);
const COLOR_FLAG: Color = Color::Rgb(191, 97, 106);
const COLOR_STR: Color = Color::Rgb(163, 190, 140);
const COLOR_COMMENT: Color = Color::Rgb(101, 115, 126);
const COLOR_DEFAULT: Color = Color::Rgb(192, 197, 206);

pub fn highlight_line(line: &str, enabled: bool) -> Line<'static> {
    if !enabled {
        return Line::from(line.to_string());
    }

    let trimmed = line.trim_start();
    if trimmed.starts_with('#') {
        return Line::from(vec![Span::styled(
            line.to_string(),
            Style::default().fg(COLOR_COMMENT),
        )]);
    }

    let mut spans = Vec::new();
    let chars: Vec<char> = line.chars().collect();
    let len = chars.len();
    let mut i = 0;
    let mut is_command_position = true;

    while i < len {
        let c = chars[i];

        if c == '#' {
            let rest: String = chars[i..].iter().collect();
            spans.push(Span::styled(rest, Style::default().fg(COLOR_COMMENT)));
            break;
        }

        if c == '\'' || c == '"' {
            let quote_char = c;
            spans.push(Span::styled(
                quote_char.to_string(),
                Style::default().fg(COLOR_DEFAULT),
            ));
            i += 1;
            let mut str_content = String::new();
            while i < len && chars[i] != quote_char {
                str_content.push(chars[i]);
                i += 1;
            }
            if !str_content.is_empty() {
                spans.push(Span::styled(
                    str_content,
                    Style::default().fg(COLOR_STR),
                ));
            }
            if i < len && chars[i] == quote_char {
                spans.push(Span::styled(
                    quote_char.to_string(),
                    Style::default().fg(COLOR_DEFAULT),
                ));
                i += 1;
            }
            is_command_position = false;
            continue;
        }

        if c == '|' || c == ';' || c == '&' {
            spans.push(Span::styled(
                c.to_string(),
                Style::default().fg(COLOR_DEFAULT),
            ));
            i += 1;
            is_command_position = true;
            continue;
        }

        if c.is_whitespace() {
            let mut ws = String::new();
            while i < len && chars[i].is_whitespace() {
                ws.push(chars[i]);
                i += 1;
            }
            spans.push(Span::styled(ws, Style::default().fg(COLOR_DEFAULT)));
            continue;
        }

        // Token
        let mut token = String::new();
        while i < len
            && !chars[i].is_whitespace()
            && chars[i] != '|'
            && chars[i] != ';'
            && chars[i] != '&'
            && chars[i] != '\''
            && chars[i] != '"'
            && chars[i] != '#'
        {
            token.push(chars[i]);
            i += 1;
        }

        if token.starts_with('-') {
            spans.push(Span::styled(token, Style::default().fg(COLOR_FLAG)));
            is_command_position = false;
        } else if is_command_position {
            spans.push(Span::styled(token, Style::default().fg(COLOR_CMD)));
            is_command_position = false;
        } else {
            spans.push(Span::styled(token, Style::default().fg(COLOR_DEFAULT)));
        }
    }

    Line::from(spans)
}
EOF"}

