    let cmd_height = (app.editor.lines.len() as u16 + 2).max(3);

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(cmd_height),
            Constraint::Min(0),
        ])
        .split(area);

    let cmd_area = chunks[0];
    let out_area = chunks[1];

    // Command Title
    let mut title_spans = vec![Span::raw(" Command")];
    if app.autoeval {
        title_spans.push(Span::styled(" [Autoeval]", Style::default().fg(Color::Cyan)));
    }
    if app.caching {
        title_spans.push(Span::styled(" [Caching]", Style::default().fg(Color::Cyan)));
    }
    if app.paranoid && app.autoeval {
        title_spans.push(Span::styled(" [Paranoid]", Style::default().fg(Color::Cyan)));
    }
    title_spans.push(Span::raw(" "));

    let cmd_block = Block::default()
        .borders(Borders::ALL)
        .title(Line::from(title_spans));

    let highlight_enabled = app.config.highlighting_enabled;
    let lines: Vec<Line> = app
        .editor
        .lines
        .iter()
        .map(|l| highlight_line(l, highlight_enabled))
        .collect();

    let cmd_paragraph = Paragraph::new(lines).block(cmd_block);
    f.render_widget(cmd_paragraph, cmd_area);

    // Set cursor position
    let cursor_x = cmd_area.x + 1 + app.editor.cursor_x as u16;
    let cursor_y = cmd_area.y + 1 + app.editor.cursor_y as u16;
    if cursor_x < cmd_area.x + cmd_area.width - 1 && cursor_y < cmd_area.y + cmd_area.height - 1 {
        f.set_cursor_position((cursor_x, cursor_y));
    }

    // Render Output / Stderr
    if app.stderr_text.is_empty() {
        let out_title = if app.has_evaluated && (app.args.default.is_some() || app.args.in_file.is_some()) {
            " Output [+] "
        } else {
            " Output "
        };

        let out_block = Block::default()
            .borders(Borders::ALL)
            .title(out_title)
            .title_bottom(Line::from("Help: F1").alignment(Alignment::Right));

        let out_paragraph = Paragraph::new(app.output_text.as_str()).block(out_block);
        f.render_widget(out_paragraph, out_area);
    } else {
        let out_chunks = Layout::default()
            .direction(Direction::Vertical)
            .constraints([Constraint::Percentage(50), Constraint::Percentage(50)])
            .split(out_area);

        let stdout_block = Block::default()
            .borders(Borders::ALL)
            .title(" Output ");
        let stdout_paragraph = Paragraph::new(app.output_text.as_str()).block(stdout_block);
        f.render_widget(stdout_paragraph, out_chunks[0]);

        let stderr_block = Block::default()
            .borders(Borders::ALL)
            .title(" Stderr ")
            .title_bottom(Line::from("Help: F1").alignment(Alignment::Right));
        let stderr_paragraph = Paragraph::new(app.stderr_text.as_str()).block(stderr_block);
        f.render_widget(stderr_paragraph, out_chunks[1]);
    }
}

fn render_popup_view(f: &mut Frame, area: Rect, app: &App) {
    let popup_width = 31.min(area.width);
    let popup_area = Rect {
        x: area.x,
        y: area.y,
        width: popup_width,
        height: area.height,
    };

    f.render_widget(Clear, popup_area);

    let lines: Vec<Line> = app
        .popup_entries
        .iter()
        .map(|(_, label, _)| Line::from(label.as_str()))
        .collect();

    let block = Block::default()
        .borders(Borders::ALL)
        .title(" Open in ");

    let paragraph = Paragraph::new(lines).block(block);
    f.render_widget(paragraph, popup_area);
}
