use std::process::Command;
use std::time::Duration;

use app::{App, PopupType, ViewMode};
use args::{parse_args, print_help};
use config::DEFAULT_CONFIG_STR;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args = match parse_args() {
        Ok(a) => a,
        Err(code) => std::process::exit(code),
    };

    if args.help {
        print_help();
        return Ok(());
    }

    if args.config_reference {
        print!("{}", DEFAULT_CONFIG_STR);
        return Ok(());
    }

    if !args.no_isolation {
        // Check if bwrap exists in PATH
        if which("bwrap").is_none() {
            println!("bubblewrap installation not found. Please make sure you have `bwrap` on your path, or supply --no-isolation to disable safe-mode");
            std::process::exit(1);
        }
    }

