    let mut terminal = Terminal::new(backend)?;

    let mut app = App::new(args);

    let res = run_app(&mut terminal, &mut app);

    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    if res.is_ok() {
        app.on_exit();
    }

    Ok(())
}

fn which(cmd: &str) -> Option<std::path::PathBuf> {
    if let Ok(path_var) = std::env::var("PATH") {
        for dir in std::env::split_paths(&path_var) {
            let full_path = dir.join(cmd);
            if full_path.is_file() {
                return Some(full_path);
            }
        }
    }
    None
}

fn run_app(
    terminal: &mut Terminal<CrosstermBackend<io::Stdout>>,
    app: &mut App,
) -> io::Result<()> {
    loop {
        terminal.draw(|f| ui::render(f, app))?;

        if event::poll(Duration::from_millis(50))? {
            if let Event::Key(key) = event::read()? {
                if key.kind != KeyEventKind::Press {
                    continue;
                }

                match &app.mode {
                    ViewMode::Help => match key.code {
                        KeyCode::F(1) | KeyCode::Esc => {
                            app.mode = ViewMode::Normal;
                        }
                        _ => {}
                    },
                    ViewMode::History | ViewMode::Bookmarks => match key.code {
                        KeyCode::F(4) if app.mode == ViewMode::History => {
                            app.mode = ViewMode::Normal;
                        }
                        KeyCode::Char('b')
                            if key.modifiers.contains(KeyModifiers::CONTROL)
                                && app.mode == ViewMode::Bookmarks =>
                        {
                            app.mode = ViewMode::Normal;
                        }
                        KeyCode::Esc => {
                            app.mode = ViewMode::Normal;
                        }
                        KeyCode::Up => {
                            app.list_selected_index = app.list_selected_index.saturating_sub(1);
                        }
                        KeyCode::Down => {
                            let len = match app.mode {
                                ViewMode::History => app.history_list.len(),
                                ViewMode::Bookmarks => app.bookmarks_list.len(),
                                _ => 0,
                            };
                            if len > 0 && app.list_selected_index + 1 < len {
                                app.list_selected_index += 1;
                            }
                        }
                        KeyCode::Backspace | KeyCode::Delete => {
                            app.handle_list_delete();
                        }
                        KeyCode::Enter => {
                            app.handle_list_select();
                        }
                        _ => {}
                    },
                    ViewMode::Popup(popup_type) => {
                        let popup_kind = match popup_type {
                            PopupType::HelpViewer => PopupType::HelpViewer,
                            PopupType::OutputViewer => PopupType::OutputViewer,
                            PopupType::Snippet => PopupType::Snippet,
                        };

                        if key.code == KeyCode::Esc {
                            app.mode = ViewMode::Normal;
                            continue;
                        }

                        if let KeyCode::Char(c) = key.code {
                            if let Some((_, _, cmd_val)) =
                                app.popup_entries.iter().find(|(k, _, _)| *k == c).cloned()
                            {
                                app.mode = ViewMode::Normal;
                                match popup_kind {
                                    PopupType::Snippet => {
                                        app.editor.insert_str_at_cursor(&cmd_val);
                                        if app.autoeval {
                                            app.evaluate();
                                        }
                                    }
                                    PopupType::HelpViewer => {
                                        run_external_viewer(terminal, &cmd_val, &app.config.eval_environment)?;
                                    }
                                    PopupType::OutputViewer => {
                                        let full_cmd = app.editor.get_full_text();
                                        let pipeline_cmd = format!("{} | {}", full_cmd, cmd_val);
                                        run_external_viewer(terminal, &pipeline_cmd, &app.config.eval_environment)?;
                                    }
                                }
                            }
                        }
                    }
                    ViewMode::Normal => match key.code {
                        KeyCode::Esc | KeyCode::Char('c')
                            if key.modifiers.contains(KeyModifiers::CONTROL) =>
                        {
                            return Ok(());
                        }
                        KeyCode::F(1) => {
                            app.mode = ViewMode::Help;
                        }
                        KeyCode::F(2) => {
                            app.toggle_autoeval();
                        }
                        KeyCode::F(3) => {
                            app.toggle_paranoid();
                        }
                        KeyCode::F(4) => {
                            app.open_history_view();
                        }
                        KeyCode::F(5) => {
                            app.open_help_viewers();
                        }
                        KeyCode::F(6) => {
                            app.open_output_viewers();
                        }
                        KeyCode::F(7) => {
                            app.toggle_cache_at_cursor();
                        }
                        KeyCode::Char('b') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                            app.open_bookmarks_view();
                        }
                        KeyCode::Char('s') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                            app.save_bookmark();
                        }
                        KeyCode::Char('p') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                            app.prev_history();
                        }
                        KeyCode::Char('n') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                            app.next_history();
                        }
                        KeyCode::Char('u') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                            app.editor.clear();
                            if app.autoeval {
                                app.evaluate();
                            }
                        }
                        KeyCode::Char('v') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                            app.open_snippets();
                        }
                        KeyCode::Enter => {
                            if key.modifiers.contains(KeyModifiers::ALT) {
                                app.editor.insert_newline();
                                if app.autoeval {
                                    app.evaluate();
                                }
                            } else {
                                app.evaluate();
                            }
                        }
                        KeyCode::Char(c) => {
                            app.editor.insert_char(c);
                            if app.autoeval {
                                app.evaluate();
                            }
                        }
                        KeyCode::Backspace => {
                            app.editor.backspace();
                            if app.autoeval {
                                app.evaluate();
                            }
                        }
                        KeyCode::Delete => {
                            app.editor.delete();
                            if app.autoeval {
                                app.evaluate();
                            }
                        }
                        KeyCode::Left => {
                            app.editor.move_left();
                        }
                        KeyCode::Right => {
                            app.editor.move_right();
                        }
                        KeyCode::Up => {
                            app.editor.move_up();
                        }
                        KeyCode::Down => {
                            app.editor.move_down();
                        }
                        KeyCode::Home => {
                            app.editor.move_home();
                        }
                        KeyCode::End => {
                            app.editor.move_end();
                        }
                        _ => {}
                    },
                }
            }
        }
    }
}

fn run_external_viewer(
    terminal: &mut Terminal<CrosstermBackend<io::Stdout>>,
    viewer_cmd: &str,
    eval_env: &[String],
) -> io::Result<()> {
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;

    if !eval_env.is_empty() {
        let _ = Command::new(&eval_env[0])
            .args(&eval_env[1..])
            .arg(viewer_cmd)
            .status();
    }

    enable_raw_mode()?;
    execute!(terminal.backend_mut(), EnterAlternateScreen)?;
    terminal.clear()?;
    Ok(())
}
