use std::fs;
use crate::config::get_config_dir;

pub fn load_list(filename: &str) -> Vec<String> {
    let path = get_config_dir().join(filename);
    if !path.exists() {
        return Vec::new();
    }
    let content = match fs::read_to_string(&path) {
        Ok(c) => c,
        Err(_) => return Vec::new(),
    };

    content
        .split("---")
        .map(|s| s.trim_matches('\n').trim_matches('\r').to_string())
        .filter(|s| !s.is_empty())
        .collect()
}

pub fn save_list(filename: &str, items: &[String]) {
    let dir = get_config_dir();
    let _ = fs::create_dir_all(&dir);
    let path = dir.join(filename);

    let content = items.join("\n---\n");
    let _ = fs::write(path, content);
}

pub fn append_history(cmd: &str, history_size: usize) {
    let trimmed = cmd.trim();
    if trimmed.is_empty() {
        return;
    }

    let mut list = load_list("history");
    if list.last().map(|s| s.as_str()) == Some(cmd) {
        return;
    }

    list.push(cmd.to_string());
    if list.len() > history_size {
        let drain_count = list.len() - history_size;
        list.drain(0..drain_count);
    }

    save_list("history", &list);
}

pub fn append_bookmark(cmd: &str) {
    let trimmed = cmd.trim();
    if trimmed.is_empty() {
        return;
    }

    let mut list = load_list("bookmarks");
    list.push(cmd.to_string());
    save_list("bookmarks", &list);
}
