use crate::args::Args;
use crate::config::{load_or_create_config, Config};
use crate::editor::Editor;
use crate::executor::execute_command;
use crate::history::{append_bookmark, append_history, load_list, save_list};

#[derive(Debug, PartialEq, Eq)]
pub enum ViewMode {
    Normal,
    Help,
    History,
    Bookmarks,
    Popup(PopupType),
}

#[derive(Debug, PartialEq, Eq, Clone, Copy)]
pub enum PopupType {
    HelpViewer,
    OutputViewer,
    Snippet,
}

pub struct App {
    pub args: Args,
    pub config: Config,
    pub editor: Editor,
    pub mode: ViewMode,
    pub autoeval: bool,
    pub paranoid: bool,
    pub caching: bool,
    pub cached_pipe_prefix: Option<String>,
    pub cached_output: Option<String>,
    pub output_text: String,
    pub stderr_text: String,
    pub has_evaluated: bool,
    pub history_list: Vec<String>,
    pub bookmarks_list: Vec<String>,
    pub history_index: Option<usize>,
    pub list_selected_index: usize,
    pub popup_entries: Vec<(char, String, String)>, // (key, label, command)
}

impl App {
    pub fn new(args: Args) -> Self {
        let config = load_or_create_config();

        let initial_text = if let Some(in_file) = &args.in_file {
            std::fs::read_to_string(in_file).unwrap_or_default()
        } else if let Some(def) = &args.default {
            def.clone()
        } else {
            String::new()
        };

        let history_list = load_list("history");
        let bookmarks_list = load_list("bookmarks");

        let autoeval = config.autoeval_mode_default;
        let paranoid = config.paranoid_history_mode_default;

        let mut app = Self {
            args,
            config,
            editor: Editor::from_str(&initial_text),
            mode: ViewMode::Normal,
            autoeval,
            paranoid,
            caching: false,
            cached_pipe_prefix: None,
            cached_output: None,
            output_text: String::new(),
            stderr_text: String::new(),
            has_evaluated: false,
            history_list,
            bookmarks_list,
            history_index: None,
            list_selected_index: 0,
            popup_entries: Vec::new(),
        };

        if autoeval {
            app.evaluate();
        }

        app
    }

    pub fn evaluate(&mut self) {
        let full_text = self.editor.get_full_text();

        let stdin_opt = if self.caching {
            if let (Some(prefix), Some(output)) = (&self.cached_pipe_prefix, &self.cached_output) {
                if full_text.starts_with(prefix) {
                    Some((full_text.trim_start_matches(prefix), output.as_str()))
                } else {
                    self.caching = false;
                    self.cached_pipe_prefix = None;
                    self.cached_output = None;
                    None
                }
            } else {
                None
            }
        } else {
            None
        };

        let result = if let Some((suffix, cached_data)) = stdin_opt {
            execute_command(
                suffix,
                &self.config.eval_environment,
                self.args.no_isolation,
                self.config.cmd_timeout_millis,
                Some(cached_data),
            )
        } else {
            execute_command(
                &full_text,
                &self.config.eval_environment,
                self.args.no_isolation,
                self.config.cmd_timeout_millis,
                None,
            )
        };

        self.output_text = result.stdout;
        self.stderr_text = result.stderr;
        self.has_evaluated = true;

        if self.paranoid && self.autoeval && self.stderr_text.is_empty() {
            append_history(&full_text, self.config.history_size);
            self.history_list = load_list("history");
        }
    }

    pub fn toggle_autoeval(&mut self) {
        self.autoeval = !self.autoeval;
        if self.autoeval {
            self.evaluate();
        }
    }

    pub fn toggle_paranoid(&mut self) {
        self.paranoid = !self.paranoid;
    }

    pub fn open_history_view(&mut self) {
        self.history_list = load_list("history");
        self.list_selected_index = self.history_list.len().saturating_sub(1);
        self.mode = ViewMode::History;
    }

    pub fn open_bookmarks_view(&mut self) {
        self.bookmarks_list = load_list("bookmarks");
        self.list_selected_index = self.bookmarks_list.len().saturating_sub(1);
        self.mode = ViewMode::Bookmarks;
    }

    pub fn save_bookmark(&mut self) {
        let text = self.editor.get_full_text();
        append_bookmark(&text);
        self.bookmarks_list = load_list("bookmarks");
    }

    pub fn toggle_cache_at_cursor(&mut self) {
        if self.editor.is_cursor_on_pipe() {
            let prefix = self.editor.get_text_up_to_cursor();
            let result = execute_command(
                &prefix,
                &self.config.eval_environment,
                self.args.no_isolation,
                self.config.cmd_timeout_millis,
                None,
            );
            self.cached_pipe_prefix = Some(prefix);
            self.cached_output = Some(result.stdout);
            self.caching = true;
            if self.autoeval {
                self.evaluate();
            }
        }
    }

    pub fn prev_history(&mut self) {
        if self.history_list.is_empty() {
            return;
        }
        let next_idx = match self.history_index {
            None => self.history_list.len().saturating_sub(1),
            Some(i) => i.saturating_sub(1),
        };
        self.history_index = Some(next_idx);
        let cmd = self.history_list[next_idx].clone();
        self.editor.set_text(&cmd);
        if self.autoeval {
            self.evaluate();
        }
    }

    pub fn next_history(&mut self) {
        if self.history_list.is_empty() {
            return;
        }
        if let Some(i) = self.history_index {
            if i + 1 < self.history_list.len() {
                let next_idx = i + 1;
                self.history_index = Some(next_idx);
                let cmd = self.history_list[next_idx].clone();
                self.editor.set_text(&cmd);
            } else {
                self.history_index = None;
                self.editor.clear();
            }
            if self.autoeval {
                self.evaluate();
            }
        }
    }

    pub fn open_help_viewers(&mut self) {
        let word = self.editor.get_word_under_cursor();
        let target = if word.is_empty() {
            self.editor.get_full_text()
        } else {
            word
        };

        self.popup_entries.clear();
        for (&k, tmpl) in &self.config.help_viewers {
            let rendered = tmpl.replace("??", &target);
            self.popup_entries.push((k, format!("{}: {}", k, rendered), rendered));
        }

        if !self.popup_entries.is_empty() {
            self.mode = ViewMode::Popup(PopupType::HelpViewer);
        }
    }

    pub fn open_output_viewers(&mut self) {
        self.popup_entries.clear();
        for (&k, cmd) in &self.config.output_viewers {
            self.popup_entries.push((k, format!("{}: {}", k, cmd), cmd.clone()));
        }

        if !self.popup_entries.is_empty() {
            self.mode = ViewMode::Popup(PopupType::OutputViewer);
        }
    }

    pub fn open_snippets(&mut self) {
        self.popup_entries.clear();
        for (&k, tmpl) in &self.config.snippets {
            let label_val = tmpl.replace("||", "");
            self.popup_entries.push((k, format!("{}: {}", k, label_val), tmpl.clone()));
        }

        if !self.popup_entries.is_empty() {
            self.mode = ViewMode::Popup(PopupType::Snippet);
        }
    }

    pub fn handle_list_delete(&mut self) {
        match self.mode {
            ViewMode::History => {
                if !self.history_list.is_empty() && self.list_selected_index < self.history_list.len() {
                    self.history_list.remove(self.list_selected_index);
                    if self.list_selected_index >= self.history_list.len() && !self.history_list.is_empty() {
                        self.list_selected_index = self.history_list.len() - 1;
                    }
                    save_list("history", &self.history_list);
                }
            }
            ViewMode::Bookmarks => {
                if !self.bookmarks_list.is_empty() && self.list_selected_index < self.bookmarks_list.len() {
                    self.bookmarks_list.remove(self.list_selected_index);
                    if self.list_selected_index >= self.bookmarks_list.len() && !self.bookmarks_list.is_empty() {
                        self.list_selected_index = self.bookmarks_list.len() - 1;
                    }
                    save_list("bookmarks", &self.bookmarks_list);
                }
            }
            _ => {}
        }
    }

    pub fn handle_list_select(&mut self) {
        match self.mode {
            ViewMode::History => {
                if !self.history_list.is_empty() && self.list_selected_index < self.history_list.len() {
                    let cmd = self.history_list[self.list_selected_index].clone();
                    self.editor.set_text(&cmd);
                    self.mode = ViewMode::Normal;
                    if self.autoeval {
                        self.evaluate();
                    }
                }
            }
            ViewMode::Bookmarks => {
                if !self.bookmarks_list.is_empty() && self.list_selected_index < self.bookmarks_list.len() {
                    let cmd = self.bookmarks_list[self.list_selected_index].clone();
                    self.editor.set_text(&cmd);
                    self.mode = ViewMode::Normal;
                    if self.autoeval {
                        self.evaluate();
                    }
                }
            }
            _ => {}
        }
    }

    pub fn on_exit(&mut self) {
        let full_text = self.editor.get_full_text();
        if !full_text.trim().is_empty() {
            append_history(&full_text, self.config.history_size);
        }

        let final_cmd = if self.args.raw_mode {
            full_text.clone()
        } else {
            full_text.replace('\n', " ")
        };

        if let Some(out_file) = &self.args.out_file {
            let _ = std::fs::write(out_file, &final_cmd);
        }

        if let Some(hook) = &self.config.finish_hook {
            let eval_env = &self.config.eval_environment;
            if !eval_env.is_empty() {
                use std::io::Write;
                use std::process::{Command, Stdio};
                if let Ok(mut child) = Command::new(&eval_env[0])
                    .args(&eval_env[1..])
                    .arg(hook)
                    .stdin(Stdio::piped())
                    .spawn()
                {
                    if let Some(mut stdin) = child.stdin.take() {
                        let _ = stdin.write_all(final_cmd.as_bytes());
                    }
                }
            }
        }

        println!("{}", final_cmd);
    }
}
