{"command":"cat << 'EOF' > src/main.rs
mod app;
mod args;
mod config;
mod editor;
mod executor;
mod highlighter;
mod history;
mod ui;

use crossterm::{
    event::{self, Event, KeyCode, KeyEventKind, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::backend::CrosstermBackend;
use ratatui::Terminal;
use std::io::{self, stdout};
use std::process::Command;
use std::time::Duration;

use app::{App, PopupType, ViewMode};
use args::{parse_args, print_help};
use config::DEFAULT_CONFIG_STR;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args = match parse_args() {
        Ok(a) => a,
        Err(code) => std::process::exit(code),
    };

    if args.help {
        print_help();
        return Ok(());
    }

    if args.config_reference {
        print!("{}", DEFAULT_CONFIG_STR);
        return Ok(());
    }

    if !args.no_isolation {
        if which("bwrap").is_none() {
            println!("bubblewrap installation not found. Please make sure you have `bwrap` on your path, or supply --no-isolation to disable safe-mode");
            std::process::exit(1);
        }
    }

    enable_raw_mode()?;
    let mut stdout_handle = stdout();
    execute!(stdout_handle, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout_handle);
    let mut terminal = Terminal::new(backend)?;

    let mut app = App::new(args);

    let res = run_app(&mut terminal, &mut app);

    disable_raw_mode()?;
    let _ = execute!(terminal.backend_mut(), LeaveAlternateScreen);
    let _ = terminal.show_cursor();

    if let Err(e) = res {
        eprintln!("Error: {}", e);
    }
    app.on_exit();

    Ok(())
}

fn which(cmd: &str) -> Option<std::path::PathBuf> {
    if let Ok(path_var) = std::env::var("PATH") {
        for dir in std::env::split_paths(&path_var) {
            let full_path = dir.join(cmd);
            if full_path.is_file() {
                return Some(full_path);
            }
        }
    }
    None
}

fn run_app(
    terminal: &mut Terminal<CrosstermBackend<io::Stdout>>,
    app: &mut App,
) -> io::Result<()> {
    loop {
        terminal.draw(|f| ui::render(f, app))?;

        if event::poll(Duration::from_millis(50))? {
            if let Event::Key(key) = event::read()? {
                if key.kind != KeyEventKind::Press {
                    continue;
                }

                match &app.mode {
                    ViewMode::Help => match key.code {
                        KeyCode::F(1) | KeyCode::Esc => {
                            app.mode = ViewMode::Normal;
                        }
                        _ => {}
                    },
                    ViewMode::History | ViewMode::Bookmarks => match key.code {
                        KeyCode::F(4) if app.mode == ViewMode::History => {
                            app.mode = ViewMode::Normal;
                        }
                        KeyCode::Char('b')
                            if key.modifiers.contains(KeyModifiers::CONTROL)
                                && app.mode == ViewMode::Bookmarks =>
                        {
                            app.mode = ViewMode::Normal;
                        }
                        KeyCode::Esc => {
                            app.mode = ViewMode::Normal;
                        }
                        KeyCode::Up => {
                            app.list_selected_index = app.list_selected_index.saturating_sub(1);
                        }
                        KeyCode::Down => {
                            let len = match app.mode {
